CREATE OR REPLACE FUNCTION trip_private.culture_quest_stats(p_card uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=p_card AND c.hidden_at IS NULL AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid()) AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND trip_private.feature_on(c.trip_id,'inspiration')) THEN jsonb_build_object('plays',(SELECT count(*) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card),'completed',(SELECT count(DISTINCT p.user_id) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'average',(SELECT coalesce(round(avg(p.score)),0) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'reactions',(SELECT count(*) FROM public.inspiration_votes v WHERE v.card_id=p_card AND v.choice='love')) ELSE NULL END $$;
REVOKE ALL ON FUNCTION trip_private.culture_quest_stats(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.culture_quest_stats(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.culture_quest_stats(p_card uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT trip_private.culture_quest_stats(p_card) $$;
REVOKE ALL ON FUNCTION public.culture_quest_stats(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.culture_quest_stats(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION trip_private.quest_item_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.card_id<>OLD.card_id THEN RAISE EXCEPTION 'Quest ownership cannot change'; END IF; IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.culture_quest_sessions s WHERE s.card_id=OLD.card_id AND s.finished_at IS NOT NULL) AND (NEW.answer IS DISTINCT FROM OLD.answer OR NEW.options IS DISTINCT FROM OLD.options OR NEW.prompt IS DISTINCT FROM OLD.prompt) THEN RAISE EXCEPTION 'Finished questions cannot change'; END IF; IF jsonb_typeof(NEW.options)<>'array' OR jsonb_array_length(NEW.options)<>4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.options) x WHERE jsonb_typeof(x)<>'string' OR length(x #>> '{}')>150) THEN RAISE EXCEPTION 'Add four short choices'; END IF; IF NEW.round_number=2 AND (NEW.photo_path IS NULL OR NOT EXISTS(SELECT 1 FROM public.cultural_inspirations c WHERE c.id=NEW.card_id AND c.photo_path=NEW.photo_path)) THEN RAISE EXCEPTION 'Picture It uses your uploaded photo'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION trip_private.culture_creator_badge(p_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN count(DISTINCT (s.card_id,p.user_id))>=250 THEN 'Heritage Hero' WHEN count(DISTINCT (s.card_id,p.user_id))>=50 THEN 'Culture Ambassador' WHEN count(DISTINCT (s.card_id,p.user_id))>=10 THEN 'Storyteller' ELSE NULL END FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id JOIN public.cultural_inspirations c ON c.id=s.card_id WHERE auth.uid() IS NOT NULL AND p.completed_at IS NOT NULL AND (c.creator_id=p_user OR c.partner_id=p_user) AND trip_private.quest_access(c.id,auth.uid()) $$;
DO $fix$ DECLARE source text; BEGIN SELECT pg_get_functiondef('trip_private.culture_quest(text,uuid,uuid,text,uuid,integer,integer)'::regprocedure) INTO source; source:=replace(source,'''session'',s.id,''card'',s.card_id,','''session'',s.id,''champion'',CASE WHEN s.finished_at IS NOT NULL THEN EXISTS(SELECT 1 FROM public.culture_stamps st WHERE st.card_id=s.card_id AND st.user_id=auth.uid() AND st.champion) ELSE false END,''card'',s.card_id,'); EXECUTE source; END $fix$;